using UnityEngine;

public class LoopBuilder : MonoBehaviour
{
    public GameObject prefab;
    public int count = 10;

    void Start()
    {
        ForLoopSpawn();
        WhileLoopSpawn();
        ForeachColorChanger();
    }

    void ForLoopSpawn()
    {
        for (int i = 0; i < count; i++)
        {
            Vector3 pos = new Vector3(i * 2f, 0, 0);
            Instantiate(prefab, pos, Quaternion.identity);
        }
    }

    void WhileLoopSpawn()
    {
        int attempts = 0;
        while (attempts < 100) // safety
        {
            Vector3 randPos = new Vector3(Random.Range(-5f, 5f), Random.Range(0f, 10f), 0);
            GameObject obj = Instantiate(prefab, randPos, Quaternion.identity);
            attempts++;
            if (randPos.y > 5f)
            {
                Debug.Log($"High spawn after {attempts} attempts at y={randPos.y}");
                break;
            }
        }
    }

    void ForeachColorChanger()
    {
        Color[] colors = { Color.red, Color.green, Color.blue, Color.yellow, Color.magenta };
        foreach (Color c in colors)
        {
            Debug.Log("Color: " + c);
        }
        // Optional: apply colors to spawned objects (not required)
    }
}
